/// <summary> Получает или устанавливает валюту </summary>
/// <param name="_currency"> Код валюты (например, USDT) </param>
/// <returns> Код валюты </returns>
[DataMember('currency')]
public str parmCurrency(str _currency = currency)
{
    currency = _currency;
    return currency;
}

